INSERT INTO project (id,slug,category_id,title,subtitle,status,status_note,summary,description,year,role,duration,featured,theme,technology_label,sort_order,features,planned_goals,verification,limitations,challenges,architecture,architecture_description,github_url,live_demo_url,local_demo_url,evidence_checked_at) VALUES ('9c7baa57-89b6-5fc5-ae84-ddac1aac047a','fadaiting-camp','8b897769-f62c-5b33-b1ea-12d13fc79f25','發呆亭','露營訂位與現場營運 · 從預約到入住退房。','In Progress','Cloud 展示階段已收尾；正式金流、通知送達與本機設備驗收留待後續。','營位保留、預約、入住退房與角色權限，包含模擬付款退款、通知重試及隔離還原。','以實際營區營運為方向的作品。顧客查詢營位與報價、建立預約；ADMIN 負責帳號與付款退款治理，STAFF 處理住宿交接、入住與退房。權限、版本與稽核由後端保護，Cloud 已完成一輪展示收尾。','2026','營運流程與全端整合','展示收尾 · 2026/10/06',true,'forest','已有實作與驗證依據的技術',0,'["營位報價、預約查詢、限時保留、取消及付款逾時釋放。", "ADMIN／STAFF 權限、帳號停用、Cookie／CSRF 與版本衝突保護。", "現場備註、入住退房、模擬付款退款核對與操作歷程。", "通知佇列、失敗重試、唯讀觀測、保留試算與 LINE token 核驗。", "PostgreSQL 備份隔離還原工具及管理員備份狀態觀測。"]'::jsonb,'["本機部署與全服務復原驗收。", "按營運需求補正式金流、通知與報表。"]'::jsonb,'["2026/10/06 保存報告：189 項後端測試通過，0 失敗／錯誤／略過；使用專用 PostgreSQL 17／Redis。", "同輪真 HTTP 21 項、production dist 瀏覽器 14 項通過，前端型別檢查與 build 成功。", "備份隔離還原另有前輪證據，不與收尾測試合併計數；此頁未重新執行營區驗收。"]'::jsonb,'["付款、退款與通知使用 mock，不代表實際扣款、轉帳或真人送達。", "本機 HTTPS、完整服務復原、實際營運資料與真手機仍待驗收。", "180 天保留是試算草案，沒有刪除排程；全站手機體驗與既有資產警告仍待改善。"]'::jsonb,'[{"title": "現場人員需要哪些權限？", "description": "以住宿操作需求區分 ADMIN／STAFF，後端限制管理入口與寫入，不只隱藏選單。"}, {"title": "重試與清理如何保留證據？", "description": "保留事件及嘗試歷程，試算時保護未知結果、金流與去重資料；試算不執行刪除。"}]'::jsonb,'["Vue 前後台", "Spring Boot／角色與交易", "PostgreSQL／Redis", "通知佇列／備份工具"]'::jsonb,'前後台共用營運服務；角色、版本、訂單與歷程由伺服器裁定，通知及備份各有操作邊界。','https://github.com/Elpsy-Deng/fadaiting-camp',NULL,NULL,'2026-10-12');
