INSERT INTO project (id,slug,category_id,title,subtitle,status,status_note,summary,description,year,role,duration,featured,theme,technology_label,sort_order,features,planned_goals,verification,limitations,challenges,architecture,architecture_description,github_url,live_demo_url,local_demo_url,evidence_checked_at) VALUES ('8ffd77ad-0dd6-5be7-a968-d6ca64e29ca4','elpsy-shop','8b897769-f62c-5b33-b1ea-12d13fc79f25','ELPSY Shop','公仔收藏品電商 · 網站、員工後台與顧客 App。','In Progress','現貨、整筆預購 MVP 與 Flutter App 第一版已有實作；真機、iOS 與正式營運待補。','現貨與預購交易、SeaweedFS 商品主圖、員工治理，以及共用後端的 Flutter 顧客 App。','公仔／收藏品單店電商。Vue 網站、Spring Boot／MyBatis 後端與獨立 Flutter App 分開維護；現貨庫存和預購批次配額各自管理。現在是開發測試版本，付款、配送、退款與通知仍為模擬。','2026','交易後端、網站與 App 整合','現貨／預購／App 第一版 · 2026/10/08',true,'peach','已有程式與驗證紀錄的技術',1,'["會員、商品／SKU、版本購物車、本人地址、訂單快照及限時庫存保留。", "模擬付款配送、退款退貨、異常付款核對與最多一次庫存回補。", "SeaweedFS 主圖、分類主檔、員工角色權限與通知 outbox。", "預購批次／獨立配額、整筆付款退款、到貨、分配及出貨前核對。", "Flutter App 共用後端；獨立 Bearer 裝置 session、refresh 輪替、安全儲存與原操作核對。"]'::jsonb,'["Android 真機與 Mac／iOS 驗收。", "本機正式部署、商家金流物流及通知串接。"]'::jsonb,'["2026/10/08 保存報告：後端 260 通過、2 個既有 fixture 略過，0 失敗／錯誤；原生真 HTTP 19 項與 DB 39 項不變條件核對通過。", "Flutter analyze 通過；unit/widget 13 通過、1 個 live socket 略過；Android debug／未簽章 release 建置成功。", "原雲端 APK 的 Android 模擬器核心 4 階段及手動 UI／生命週期 8 項通過；Vue production build 成功。"]'::jsonb,'["付款、退款、配送與通知仍為 mock，網站未正式營業，App 未正式上架。", "完整 App UI 自動化有 ANR／逾時及背景黑畫面紀錄，需真機覆驗；iOS 未做 Xcode build。", "交付的 CI 重建 APK 與雲端驗收 APK 雜湊／簽章不同，交付檔尚未裝置驗收；正式簽章、HTTPS 仍待補。", "訂金尾款、延期、部分退款、多圖是後續擴充，不追加為整筆預購 MVP 完成條件。"]'::jsonb,'[{"title": "現貨與預購如何避免混扣？", "description": "庫存與批次配額分離，保存訂單快照，取消、逾時、付款與履約在後端交易內核對。"}, {"title": "App 斷線後如何核對？", "description": "保存原 owner／UUID／body；UUID 操作核對原請求，版本寫入先讀確認，ACK 後 GET 失敗不重新下單。"}]'::jsonb,'["Vue／Flutter", "Spring Boot／MyBatis", "MySQL／Redis Session", "SeaweedFS／Outbox"]'::jsonb,'Web 與 App 共用商品、會員及交易；網站 Cookie／CSRF 與 App Bearer realm 隔離，不複製後端資料庫。','https://github.com/Elpsy-Deng/Shop_back',NULL,NULL,'2026-10-12');
