INSERT INTO project (id,slug,category_id,title,subtitle,status,status_note,summary,description,year,role,duration,featured,theme,technology_label,sort_order,features,planned_goals,verification,limitations,challenges,architecture,architecture_description,github_url,live_demo_url,local_demo_url,evidence_checked_at) VALUES ('fb6f2da2-474c-51d5-ab94-7ffa404ee1d2','ticket-platform','a821a23c-8ee8-573a-b959-c0ad6af418ec','Encore · 售票平台','排隊、Queue 與 Redis 預扣 · 故障中的交易一致性。','In Progress','M6D 受控 Cloud 展示已結案；持續預扣、公開部署與正式售票營運尚未完成。','排隊與非同步購票、Redis Lua 預扣、多 API／Worker 故障恢復、QR 驗票及有界 k6／還原證據。','以有限票額競爭、冪等及故障恢復為主題。PG 是正式訂單與票額來源，Redis 控制入口，RabbitMQ 交付持久購票工作。已完成受控展示，202 受理不代表保票，付款仍是免費 mock。','2026','交易一致性與非同步全端實作','M1–M6D · 2026/10/12 收尾',true,'violet','已有程式與限定環境證據的技術',2,'["活動／場次／票種及權限；PG 保票、限購、取消到期與模擬付款。", "Redis 等候室／資格；持久請求、Outbox、confirm、提交後 ACK 與 MQ 去重。", "Lua ledger、generation／intent／decision 核對、有限返還授權及人工 REVIEW。", "同 JAR 的 API／nonweb Worker、共享 Session、基本監控與多實例故障驗證。", "明確領票、QR 圖片／相機入口、一次驗票／撤銷、時間窗與有界 PG 還原。"]'::jsonb,'["先解 DIRTY 接續及授權輪替，再做暖機、多輪與長時間負載。", "本機最新部署、HTTPS、真手機與全服務復原。"]'::jsonb,'["M6D 保存報告：真 PG／Redis／RabbitMQ 的 629 項後端測試，0 失敗／錯誤／略過；前端 build、瀏覽器 10 組與 PG 7 項核對通過。", "M6B：每組 60 顧客、12 票、8 VU；807 HTTP／819 checks、55 項零違規。同步／非同步各保票 12 張，預扣 8 張。", "M6C：74 表／178 筆隔離還原、10 組驗收、67 項零違規；3 個原 pending 各只成立一張訂單。"]'::jsonb,'["持續預扣部分完成：M6B 在 8/12 張後進入 DIRTY gate，餘 4 張不能接續；不能宣稱持續高吞吐或最大容量。", "Redis／PG／MQ 仍單節點，無 Cluster、跨主機 HA 或 exactly-once 保證。", "完整 Nginx 多節點容器證據是歷史 V22，最新 V24 全套未重驗；IP 變更須 reload。", "備份是有界離線 PG 還原，不含 Redis／MQ volume、PITR；HTTPS、真手機、正式服務及全服務切換待驗。"]'::jsonb,'[{"title": "受理與保票是不同結果", "description": "先保存請求／Outbox，再至少一次投遞 Worker；只有正式保票 commit 才成立訂單，未知回覆核對原 UUID。"}, {"title": "安全停止也要展示", "description": "來源推進後 gate 拒絕新流量，保留真實 8/12 與剩票結果，不以重建投影或換 UUID 包裝高吞吐。"}]'::jsonb,'["Vue／Nginx／API", "PG 請求與 Outbox", "RabbitMQ／Worker", "Redis Lua／PG 正式票額"]'::jsonb,'模組化單體按 API／Worker 角色運行；PG 裁定交易，Redis 與 MQ 故障窗口依原身分及持久證據有限恢復。','https://github.com/Elpsy-Deng/ticket-platform',NULL,NULL,'2026-10-12');
