INSERT INTO project (id,slug,category_id,title,subtitle,status,status_note,summary,description,year,role,duration,featured,theme,technology_label,sort_order,features,planned_goals,verification,limitations,challenges,architecture,architecture_description,github_url,live_demo_url,local_demo_url,evidence_checked_at) VALUES ('981332a4-7d7b-59eb-9899-d455f5aa2295','ai-knowledge-assistant','938e956e-e841-5c8d-8955-b39e2a0fe722','Atlas · AI Knowledge Assistant','免費本地 RAG · 混合檢索、模型回答與來源核對。','In Progress','真實本地模型與權限展示已有驗證；預設離線，品質與使用者本機驗收仍待補。','Qwen3 4B、BGE-M3、Qdrant、BM25＋RRF、BGE 重排與來源版本核對，保留品質失敗案例。','Java／Spring Boot 與 Vue 文件助理，保留 BM25 baseline，明確啟用後使用免費本地模型。依伺服器身分與文件權限檢索、融合、重排、生成及核對引用。長推論以背景工作交付，引用有效仍不代表語意正確。','2026','RAG、來源版本與權限整合','免費 RAG／品質／登入展示 · 2026/10/06',true,'blue','已有真實推論或程式驗證的技術',3,'["Markdown 匯入更新刪除、版本、chunk ID、行號及 canonical source 核對。", "BGE-M3／Qdrant 向量檢索、BM25＋RRF、BGE 重排及 Qwen3 4B 本地生成。", "伺服器登入與文件權限，發布時重驗身分、到期與版本。", "202 背景提問工作與短請求查詢、檢索階段及模型 usage。", "凍結題集、本地 Ragas 子集／控制案例、啟停與版本化備份工具。"]'::jsonb,'["獨立人工語意覆核與品質改善。", "使用者本機模型、部署與個人文件驗收。"]'::jsonb,'["保存的第四里程碑：40 題完整功能 37/40，保留題 22/24；共同編寫題集，不是獨立語意準確率。", "最新規範回歸：45 項後端測試與前端 build 通過；該輪為 stub／隔離 store，未重跑推論。", "另有真實本地 CPU 推論、歷史外部提問及來源核對證據；舊 Tunnel 不當成目前可用 Demo。"]'::jsonb,'["仍有漏必要條件、誤拒答及刪除／到期原因混淆；引用核對不代表支持全部答案。", "Ragas 是本地模型子集評分，未有獨立人工標註，不宣稱通用準確率或正式效能。", "預設 offline，模型需明確安裝啟用；個人文件、本機多作品部署、長期負載與完整使用者治理待補。"]'::jsonb,'[{"title": "引用存在不代表答案正確", "description": "核對版本與原文之外，保留漏條件與錯誤因果案例，分開呈現功能檢查及語意覆核。"}, {"title": "長推論如何處理身分變動？", "description": "發布時重驗權限與版本，認證變更後丟棄舊回應，不信任客戶端自報角色。"}]'::jsonb,'["Vue／背景提問 API", "身分與版本化文件", "BGE-M3／Qdrant＋BM25", "RRF／重排／Qwen3／引用核對"]'::jsonb,'授權快照→混合檢索→重排→本地模型→原文與版本核對；離線摘錄保留，沒有付費 API fallback。','https://github.com/Elpsy-Deng/ai-knowledge-assistant',NULL,NULL,'2026-10-12');
