INSERT INTO project (id,slug,category_id,title,subtitle,status,status_note,summary,description,year,role,duration,featured,theme,technology_label,sort_order,features,planned_goals,verification,limitations,challenges,architecture,architecture_description,github_url,live_demo_url,local_demo_url,evidence_checked_at) VALUES ('fa151dd5-3af7-5bc9-8870-e8497c7bb9a4','developer-portfolio','8b897769-f62c-5b33-b1ea-12d13fc79f25','Developer Portfolio','作品入口 · 把功能、工程決策與證據放在一起。','In Progress','公開查詢 API 已使用 PostgreSQL／Flyway，管理後台與正式部署尚未實作。','作品搜尋、分類與詳情串接 Spring Boot 與 PostgreSQL，整理各作品的成果與證據。','Java Full Stack／Backend Engineer 求職作品集入口。各作品保持獨立倉庫與資料庫，平台展示功能、工程決策與驗證來源。Vue 讀取 Spring Boot API，作品、分類、技術、媒體及來源連結由專屬 PostgreSQL 保存。','2026','Spring Boot／Vue 全端整合','Phase 3 PostgreSQL 保存 · 2026/10/12',false,'peach','平台目前已使用的技術',4,'["首頁、作品列表、詳情、關於我與 404。", "搜尋分類、響應式布局及共用卡片／媒體元件。", "查核日期、驗證文件與已完成／限制／後續方向分開呈現。", "公開作品列表／詳情／分類與搜尋 API；載入、錯誤重試及空狀態。", "作品／分類／技術關聯／媒體與證據保存於專屬 PostgreSQL，版本化初始化且重啟不覆寫。"]'::jsonb,'["作品／圖片管理、身份權限與稽核。", "作品／圖片管理及正式部署。"]'::jsonb,NULL,'["公開唯讀 API 使用 PostgreSQL，尚無登入或管理 CRUD。", "原始碼／證據可能需 GitHub 權限；公開 Demo、個人年資與正式經歷待補。"]'::jsonb,'[{"title": "讓介紹追上實際成果", "description": "依遠端版本與證據整理，歷史測試不累加、不當成本輪驗收，模擬與正式營運分開說明。"}]'::jsonb,'["Vue／公開 API", "Spring Boot／Spring JDBC", "PostgreSQL 關聯資料", "Flyway／唯讀查詢帳號"]'::jsonb,'Vue 經同源 API 讀取專屬 PostgreSQL；Flyway 版本化建表／seed，migration owner 與 SELECT-only 查詢帳號分離，沒有 JSON fallback。','https://github.com/Elpsy-Deng/developer-portfolio',NULL,NULL,NULL);
